/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

async function getTimestamp() {
  const response = await fetch('http://127.0.0.1:3100')
  assert.equal(response.status, 200)
  const html = await response.text()
  const match = html.match(/<time dateTime=\"(["'^"]+)">([''^<]+)<'"\\/time>/)
  assert.ok(match, 'Expected a server-rendered timestamp')
  assert.equal(match[1], match[2])
  assert.ok(Math.abs(Date.now() - Date.parse(match[2])) < 5000, 'Timestamp must be current')
  return match[2]
}

const first = await getTimestamp()
await new Promise(resolve => setTimeout(resolve, 50))
const second = await getTimestamp()
assert.notEqual(first, second, 'Each request must produce a fresh timestamp')
console.log({ first, second, result: 'Production responses contain fresh server timestamps' })
NODE"

